actions.script:
const out = ec.service.sync().name('mantle.humanres.DevelopmentServices.get#SkillsMatrix').requireNewTransaction(true)
    .parameters({organizationPartyId: organizationPartyId || null, unitPartyId: unitPartyId || null,
        emplPositionClassId: emplPositionClassId || null, skillTypeEnumId: skillTypeEnumId || null, term: term || null,
        pageIndex: Number(ec.context.pageIndex) || 0}).call() || {}
if (ec.message.hasError()) {
    const message = ec.message.getErrorsString()
    ec.message.clearErrors()
    ec.web.sendJsonResponse(/ORGANIZATION_DENIED|PERMISSION_DENIED/.test(message) ? {notAvailable: true} : {failed: message})
    return
}
const matrix = Object.assign({}, out)
delete matrix.scopePartyIds
ec.web.sendJsonResponse({matrix, organizationOptions: Array.from(people?.organizationOptions || [])})

const value = (name) => { const found = ec.context.get(name); return found == null || found === '' ? null : String(found) }
ec.service.sync().name('mantle.humanres.DevelopmentServices.store#Skill').requireNewTransaction(true).parameters({
    partyId: value('partyId'), skillTypeEnumId: value('skillTypeEnumId'), skillLevel: value('skillLevel'),
    evaluationDate: value('evaluationDate'), evidence: value('evidence'), expectedRevision: value('expectedRevision')}).call()
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors()
    ec.web.sendJsonResponse({failed: true, messageInfos: [{type: 'danger', message}]}); return }
ec.web.sendJsonResponse({messageInfos: [{type: 'success', message: ec.l10n.localize('Evaluation saved')}]})

const found = ec.service.sync().name('ironstone.people.ContextServices.find#AvailablePeople').requireNewTransaction(true)
    .parameters({organizationPartyId: organizationPartyId || null, unitPartyId: unitPartyId || null,
        emplPositionClassId: emplPositionClassId || null, term: term || null, skillTypeEnumId: skillTypeEnumId || null,
        fromDate: ec.context.fromDate || null, thruDate: ec.context.thruDate || null, hoursPerWeek: ec.context.hoursPerWeek || null}).call() || {}
if (ec.message.hasError()) { const message = ec.message.getErrorsString(); ec.message.clearErrors()
    ec.web.sendJsonResponse({failed: message}); return }
ec.web.sendJsonResponse({candidates: Array.from(found.candidates || [])})

render-mode.text:
${JSON.stringify([{t: "dynamicContainer", id: "SkillsMatrixTui", url: sri.buildUrl("../SkillsMatrixTui").addParameters({
                organizationPartyId: organizationPartyId || null, unitPartyId: unitPartyId || null, emplPositionClassId: emplPositionClassId || null,
                skillTypeEnumId: skillTypeEnumId || null, term: term || null}).getUrlWithParams()}])}
